let currentCandName = 'Tsai Ing-Wen';
let currentCandTitle = 'President';
let currentMateName = 'Chen Chien-jen';
window.currentMateName = currentMateName; // 顺手拷贝一份给全局
let currentMateTitle = 'Vice President';
var PollAdjustmentCache = {};

// ==============================================================
// 预防性补丁：防崩溃函数 (防止 ReferenceError)
// ==============================================================
window.changePlaylist = function(playlistName) {
    console.log("【系统提示】尝试切换背景音乐至: " + playlistName + "，但功能已停用，已忽略此操作。");
};
// 政策分数动态偏移工具 (自动防止分数超出 -1.0 到 1.0 的极限)
window.shiftIssueScore = function(issue_id, amount, candidate_id) {
    if (typeof campaignTrail_temp === 'undefined' || !campaignTrail_temp.candidate_issue_score_json) return;
    
    // 如果没有手动指定 candidate_id，则自动获取玩家当前的候选人 PK，默认备用值为 67
    let targetCandidate = candidate_id || campaignTrail_temp.candidate_id || 67;
    
    // 在 JSON 中匹配 当前候选人 (fields.candidate) 和 议题 ID (fields.issue)
    let issueObj = campaignTrail_temp.candidate_issue_score_json.find(i => 
        i.fields.candidate === targetCandidate && i.fields.issue === issue_id
    );
    
    if (issueObj) {
        let newScore = issueObj.fields.issue_score + amount;
        // 强制卡在 -1.0 到 1.0 之间
        issueObj.fields.issue_score = Math.max(-1.0, Math.min(1.0, newScore));
    }
};

// 显式挂载到全局 window 对象
window.ctsAchievement = function(achievement, difficultyChecker = true) {
    if ((difficultyChecker && campaignTrail_temp.difficulty_level_multiplier <= 1) || !difficultyChecker) {
        if (campaignTrail_temp.CTS) {
            unlockAchievement(achievement);
        }
    }
};
// ==========================================================================
// 🛡️ 大选后台记账引擎（必须放在 Code 2 最顶部，确保答题时绝对不崩溃）
// ==========================================================================
window.PollModifiers_Raw = window.PollModifiers_Raw || {};
window['2018ELECTIONHOLD'] = window['2018ELECTIONHOLD'] || 0;
window.Election2018_Flags = {};

// 核心修复：让 PollModifiers 从游戏诞生的第一毫秒起就是一个合法的 Proxy
window.PollModifiers = new Proxy(window.PollModifiers_Raw, {
    set: function(target, property, value) {
        target[property] = value;
        // 如果玩家已经打开过 data center，这里会自动触发刷新；没打开过则静默记账
        if (typeof window.RefreshElectionMap === 'function') {
            window.RefreshElectionMap();
        }
        return true;
    },
    get: function(target, property) {
        return target[property];
    }
});
window.setMultiplier = function(party, amount) {
    window.PartyMultipliers[party] = amount;
};
window.PartyMultipliers = window.PartyMultipliers || {
    'KMT': 1.0,  
    'DPP': 1.0,
    'IND': 1.07,
    'MKT': 1
};

// 推荐在 TCT 剧情里使用这两个函数，比直接写方括号更安全
window.addPoll = function(modifierKey, amount) {
    window.PollModifiers[modifierKey] = (window.PollModifiers[modifierKey] || 0) + amount;
};
window.setPoll = function(modifierKey, amount) {
    window.PollModifiers[modifierKey] = amount;
};
