function updateQuestionBanner() {
   // 1. 獲取當前問題的索引 (直接就是 0, 1, 2...)
    const currentQIndex = campaignTrail_temp.question_number;
    
    const picWidth = 160;
    const picHeight = 203;
    
    // 2. 查找 DOM 元素
    let questionBanner = document.getElementById("campaign_sign");
    document.getElementById("header").src = "https://file.garden/Z9XHdyLGHwUEZPS4/ROC%202020/bannertsai.jpg?v=1783524736028";
    
   // 檢查舊元素
    if (!questionBanner || questionBanner.nodeName != "DIV") return;
    
   // 3. 創建圖片元素
    let img = document.createElement('img');
    let imageSource = null;
    
    
    
   // 4. 核心 MOD 判斷邏輯：確保索引有效
    if (currentQIndex >= 0 && currentQIndex < MOD_IMAGE_URLS.length) {
        
        // ** 直接使用索引從 Mod 陣列中取圖 **
        imageSource = MOD_IMAGE_URLS[currentQIndex];
        // 額外：如果您想設定背景，可以在這裡執行
      $("#game_window")[0].style.backgroundColor = '#1b9431';
    } else {
        // 索引無效時的後備圖片
        imageSource = 'https://i.imgur.com/Default_Fallback_Image.png';
        console.warn(`Mod 警告: 索引 ${currentQIndex} 無效，使用後備圖片。`);
    }
    
    // 5. 設定圖片 src
    img.src = imageSource;
    
    // 6. 替換舊元素
    questionBanner.replaceWith(img);
}
    

/**
 * 遍历并替换 candidate_pic 和 running_mate_pic 元素，
 * 将它们包裹在带有指定样式和文本的容器中。
 */
/**
 * 遍历并替换 candidate_pic 和 running_mate_pic 元素，
 * 将它们包裹在带有指定样式和文本的容器中。
 * * @param {string} candName - 候选人姓名
 * @param {string} candTitle - 候选人职务/头衔
 * @param {string} mateName - 副手或政党名称
 * @param {string} mateTitle - 副手职务或政党头衔
 */
function createAllCandidateBoxes(candName, candTitle, mateName, mateTitle) {
    const picWidth = 160;
    const picHeight = 203;

    // =========================================================
    // 1. 候选人信息卡片重构 (左侧)
    // =========================================================
    const originalPic = document.getElementById('candidate_pic');
    
    if (originalPic && !document.getElementById('candidate_box_wrapper')) {
        const wrapper = document.createElement('div');
        wrapper.id = 'candidate_box_wrapper';
        wrapper.style.cssText = `
            background: #FFFFFF !important; /* 纯白无渐变容器底色 */
            border: 1px solid #BCBCBC !important; /* 纯正的系统细边框线 */
            border-radius: 2px !important; /* 方正微圆角，严谨对齐图片按钮 */
            padding: 8px !important;
            text-align: center !important;
            display: inline-block !important;
            box-shadow: 0 2px 8px rgba(0,0,0,0.05) !important; /* 极轻量的硬朗系统投影 */
            float: left !important;
            margin-left:8em !important; 
            margin-right: 15px !important;
            max-width: ${picWidth + 16}px !important;
            font-family: 'Segoe UI', 'Microsoft YaHei', sans-serif !important;
            transition: background 0.1s, border-color 0.1s !important;
        `;

        // Win10 桌面控件交互：绝不上浮，仅进行边框变色与底色微调反馈
        wrapper.onmouseenter = () => { 
            wrapper.style.borderColor = '#0078D7';
            wrapper.style.background = '#F9F9F9';
        };
        wrapper.onmouseleave = () => { 
            wrapper.style.borderColor = '#BCBCBC';
            wrapper.style.background = '#FFFFFF';
        };

        const pic = originalPic.cloneNode(true);
        pic.id = '';
        pic.style.width = `${picWidth}px`;
        pic.style.height = `${picHeight}px`;
        pic.style.objectFit = 'cover';
        pic.style.borderRadius = '2px'; /* 对齐系统照片框 */
        pic.style.border = '1px solid #D2D2D2';

        const nameDiv = document.createElement('div');
        nameDiv.textContent = candName; 
        nameDiv.style.cssText = 'color: #000000; font-size: 14.5px; font-weight: 600; margin-top: 10px; letter-spacing: 0.5px;';

        const titleDiv = document.createElement('div');
        titleDiv.textContent = candTitle; 
        titleDiv.style.cssText = 'color: #555555; font-size: 12px; margin-top: 4px; line-height: 1.3; padding-bottom: 2px;';

        wrapper.appendChild(pic);
        wrapper.appendChild(nameDiv);
        wrapper.appendChild(titleDiv);

        originalPic.parentNode.replaceChild(wrapper, originalPic);
    }

    // =========================================================
    // 2. 副手/政党信息卡片重构 (右侧)
    // =========================================================
    const originalMatePic = document.getElementById('running_mate_pic');

    if (originalMatePic && !document.getElementById('running_mate_box_wrapper')) {
        const mateWrapper = document.createElement('div');
        mateWrapper.id = 'running_mate_box_wrapper'; 
        mateWrapper.style.cssText = `
            background: #FFFFFF !important;
            border: 1px solid #BCBCBC !important;
            border-radius: 2px !important;
            padding: 8px !important;
            text-align: center !important;
            display: inline-block !important;
            box-shadow: 0 2px 8px rgba(0,0,0,0.05) !important;
            float: right !important; 
            margin-right: 8em !important; 
            margin-left: 15px !important;
            max-width: ${picWidth + 16}px !important;
            font-family: 'Segoe UI', 'Microsoft YaHei', sans-serif !important;
            transition: background 0.1s, border-color 0.1s !important;
        `;

        // 统一右侧卡片的桌面级无缝交互
        mateWrapper.onmouseenter = () => { 
            mateWrapper.style.borderColor = '#0078D7';
            mateWrapper.style.background = '#F9F9F9';
        };
        mateWrapper.onmouseleave = () => { 
            mateWrapper.style.borderColor = '#BCBCBC';
            mateWrapper.style.background = '#FFFFFF';
        };

        const matePic = originalMatePic.cloneNode(true);
        matePic.id = ''; 
        matePic.style.width = `${picWidth}px`;
        matePic.style.height = `${picHeight}px`;
        matePic.style.objectFit = 'cover';
        matePic.style.borderRadius = '2px';
        matePic.style.border = '1px solid #D2D2D2';

        const mateNameDiv = document.createElement('div');
        mateNameDiv.textContent = mateName; 
        mateNameDiv.style.cssText = 'color: #000000; font-size: 14.5px; font-weight: 600; margin-top: 10px; letter-spacing: 0.5px;';

        const mateTitleDiv = document.createElement('div');
        mateTitleDiv.textContent = mateTitle; 
        mateTitleDiv.style.cssText = 'color: #555555; font-size: 12px; margin-top: 4px; line-height: 1.3; padding-bottom: 2px;';

        mateWrapper.appendChild(matePic);
        mateWrapper.appendChild(mateNameDiv);
        mateWrapper.appendChild(mateTitleDiv);

        originalMatePic.parentNode.replaceChild(mateWrapper, originalMatePic);
    }
}
