        campaignTrail_temp.running_mate_issue_score_json.forEach(function(item) {
            if (item.fields && item.fields.candidate === 50001 && scoreMap.hasOwnProperty(item.fields.issue)) {
                item.fields.issue_score = scoreMap[item.fields.issue];
            }
        });
