window.modKMTWeight = function(key, amount) {
    const defaults = {
        'weight_ma': 0.0,
        'weight_chu': 0.4,
        'weight_wu': 0.7,
        'weight_gou': 0.3,
        'weight_hung': 0.1,
        'weight_han': 0.1,
        'weight_wang': 0.4
    };
    
    let current = window[key] !== undefined ? window[key] : (defaults[key] !== undefined ? defaults[key] : 0.5);
    current += amount;
    if (current < 0.0) current = 0.0;
    window[key] = current;
};
// ==========================================================================
// 1. KMT 提名精算函数 (修正题号 18 错位与强制覆盖重写版)
// ==========================================================================
window.calculateKMTNominationWeights = function(e) {
    let hasAnswers = (typeof campaignTrail_temp !== 'undefined' && campaignTrail_temp && Array.isArray(campaignTrail_temp.player_answers));
    let ans = hasAnswers ? campaignTrail_temp.player_answers : [];
    
    // 核心修复：第 19 题对应的真实序号是 18 (ans.length >= 18 或 question_number >= 18)
    let isQ19 = (
        ans.length >= 18 || 
        (typeof campaignTrail_temp !== 'undefined' && campaignTrail_temp && campaignTrail_temp.question_number >= 18)
    );

    // 校验赖清德线
    let isLaiWinner = (
        (typeof e !== 'undefined' && e && Number(e.lai) === 1) || 
        (typeof campaignTrail_temp !== 'undefined' && campaignTrail_temp && (
            Number(campaignTrail_temp.lai) === 1 || ans.includes(20504)
        ))
    );

    // 校验马英九出线条件
    let selected412407 = ans.includes(412407);
    let isKmt2018Win = (
        (typeof e !== 'undefined' && e && e.Wins2018election == 1) || 
        (typeof campaignTrail_temp !== 'undefined' && campaignTrail_temp && campaignTrail_temp.Wins2018election == 1) ||
        ans.includes(20440) || ans.includes(20436)
    );
    let isMaEligible = !isLaiWinner && selected412407 && isKmt2018Win && isQ19;

    // 核心修复：只要马英九满足条件，无视任何先前的错锁，强行重写胜者为马英九！
    if (isMaEligible) {
        console.log(">>> [FIX APPLIED] Overriding settled winner to Ma Ying-jeou!");
        window.kmt_primary_settled_winner = 'weight_ma';
        window.weight_ma = 10.0;
        window.weight_chu = 0.0;
        window.weight_wu = 0.0;
        window.weight_gou = 0.0;
        window.weight_hung = 0.0;
        window.weight_wang = 0.0;
        window.weight_han = 0.0;

        let allFlags = ['mayingjiu', 'hanguoyu', 'zhulilun', 'guotaiming', 'wudunyi', 'wangjinping', 'hongxiuzhu'];
        allFlags.forEach(f => {
            if (typeof e !== 'undefined' && e) e[f] = 0;
            if (typeof campaignTrail_temp !== 'undefined' && campaignTrail_temp) campaignTrail_temp[f] = 0;
            if (typeof window !== 'undefined') window[f] = 0;
        });

        if (typeof e !== 'undefined' && e) e.mayingjiu = 1;
        if (typeof campaignTrail_temp !== 'undefined' && campaignTrail_temp) campaignTrail_temp.mayingjiu = 1;
        if (typeof window !== 'undefined') window.mayingjiu = 1;
        return;
    }

    // 未到第 19 题且马英九未触发，暂不进行常规锁死
    if (!isQ19 && typeof window.kmt_primary_settled_winner === 'undefined') {
        return;
    }

    // 赖清德线强锁韩国瑜
    if (isLaiWinner) {
        window.kmt_primary_settled_winner = 'weight_han';
        window.weight_han = 10.0;
        window.weight_chu = 0.0;
        window.weight_wu = 0.0;
        window.weight_gou = 0.0;
        window.weight_hung = 0.0;
        window.weight_wang = 0.0;
        window.weight_ma = 0.0;
        return;
    }

    // 蔡英文线常规结算
    let flags = window.Election2018_Flags || window.flags || {};
    let isDpp2018Win = (typeof campaignTrail_temp !== 'undefined' && campaignTrail_temp && campaignTrail_temp.Wins2018election == 2);
    let angry = (typeof campaignTrail_temp !== 'undefined' && campaignTrail_temp) ? (campaignTrail_temp.publicangry || 0) : 0;

    let prereq_wu = !isDpp2018Win && (flags['Taipei'] === 'KMT' && flags['Kaohsiungcity'] === 'KMT' && flags['Taichung'] === 'KMT');
    let prereq_wang = !isDpp2018Win && (isKmt2018Win && angry < 5);
    let prereq_gou = !isDpp2018Win && isKmt2018Win;
    let prereq_han = !isDpp2018Win && (flags['Kaohsiungcity'] === 'KMT');
    let prereq_chu = true; 
    let prereq_hung = isDpp2018Win;

    let candidates = [
        { key: 'weight_wu', flag: 'wudunyi', prereq: prereq_wu, weight: window.weight_wu || 0.7, rank: 6 },
        { key: 'weight_wang', flag: 'wangjinping', prereq: prereq_wang, weight: window.weight_wang || 0.4, rank: 5 },
        { key: 'weight_gou', flag: 'guotaiming', prereq: prereq_gou, weight: window.weight_gou || 0.3, rank: 4 },
        { key: 'weight_han', flag: 'hanguoyu', prereq: prereq_han, weight: window.weight_han || 0.1, rank: 3 },
        { key: 'weight_chu', flag: 'zhulilun', prereq: prereq_chu, weight: window.weight_chu || 0.4, rank: 2 },
        { key: 'weight_hung', flag: 'hongxiuzhu', prereq: prereq_hung, weight: window.weight_hung || 0.1, rank: 1 }
    ];

    let eligible = candidates.filter(c => c.prereq === true);
    eligible.sort((a, b) => (b.weight !== a.weight) ? (b.weight - a.weight) : (b.rank - a.rank));

    let winner = eligible[0] || candidates.find(c => c.key === 'weight_chu');

    let keys = ['weight_ma', 'weight_wu', 'weight_wang', 'weight_gou', 'weight_han', 'weight_chu', 'weight_hung'];
    keys.forEach(k => { window[k] = 0.0; });

    window[winner.key] = 10.0;
    window.kmt_primary_settled_winner = winner.key;

    let allFlags = ['mayingjiu', 'hanguoyu', 'zhulilun', 'guotaiming', 'wudunyi', 'wangjinping', 'hongxiuzhu'];
    allFlags.forEach(f => {
        if (typeof e !== 'undefined' && e) e[f] = 0;
        if (typeof campaignTrail_temp !== 'undefined' && campaignTrail_temp) campaignTrail_temp[f] = 0;
        if (typeof window !== 'undefined') window[f] = 0;
    });

    if (winner && winner.flag) {
        if (typeof e !== 'undefined' && e) e[winner.flag] = 1;
        if (typeof campaignTrail_temp !== 'undefined' && campaignTrail_temp) campaignTrail_temp[winner.flag] = 1;
        if (typeof window !== 'undefined') window[winner.flag] = 1;
    }
};
