// 终极动态总统加冕系统 (民进党绿色版)
// ==============================================================
window.changePresidentAndShowOverlay = function(presName, presTitle, presImage, presShortDesc, presBio) {
    
    let pres_html = `
        <div id='dynamic_pres_mask' style='position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; background: rgba(0,0,0,0.75); z-index: 99999; display: flex; justify-content: center; align-items: center;'>
            <div style='background: #fdfdfc; border: 4px solid #1b9431; padding: 30px; width: 750px; max-height: 90vh; overflow-y: auto; box-shadow: 15px 15px 0px rgba(0,0,0,0.8); font-family: Tahoma, sans-serif; text-align: left; color: #111;'>
                
                <div style='border-bottom: 3px solid #1b9431; padding-bottom: 10px; margin-bottom: 20px;'>
                    <h2 style='margin: 0; color: #1b9431; font-size: 24px; text-transform: uppercase; letter-spacing: 1px;'>Official Presidential Nominee</h2>
                    <p style='margin: 5px 0 0 0; color: #666; font-size: 14px; font-style: italic;'>The Republic of China (Taiwan) - Democratic Progressive Party</p>
                </div>

                <div style='display: flex; gap: 20px;'>
                    <div style='flex-shrink: 0; width: 240px; display: flex; flex-direction: column; gap: 10px;'>
                        <div style='border: 2px solid #333; width: 100%; height: 320px; background: #fff; overflow: hidden; box-shadow: 3px 3px 5px rgba(0,0,0,0.2);'> 
                            <img src='${presImage}' style='width: 100%; height: 100%; object-fit: cover; object-position: center top; display: block;' alt='President'> 
                        </div>
                        <div style='background: #EEE; border: 1px solid #CCC; padding: 10px; text-align: center;'>
                            <div style='font-size: 18px; font-weight: bold; color: #1b9431; margin-bottom: 5px;'>${presName}</div>
                            <div style='font-size: 12px; color: #444; font-weight: bold; text-transform: uppercase;'>${presTitle}</div>
                        </div>
                    </div>
                    
                    <div style='flex-grow: 1; display: flex; flex-direction: column;'>
                        <div style='background: #1b9431; color: #FFF; padding: 10px 15px; font-size: 13px; font-weight: bold; line-height: 1.5; border-radius: 2px; margin-bottom: 15px; box-shadow: inset 0 0 10px rgba(0,0,0,0.3);'>
                            ${presShortDesc}
                        </div>
                        <div style='font-size: 12px; color: #888; text-transform: uppercase; border-bottom: 1px solid #CCC; margin-bottom: 10px; padding-bottom: 3px; font-weight: bold;'>Political Biography</div>
                        <div style='overflow-y: scroll; height: 260px; padding: 10px; background: #FFF; border: 1px solid #CCC; font-size: 14px; line-height: 1.6; color: #333;'>
                            ${presBio}
                        </div>
                    </div>
                </div>

                <div style='text-align: right; margin-top: 20px;'> 
                    <button id='pres_continue_button' style='padding: 10px 30px; background-color: #1b9431; color: #FFFFFF !important; border: 2px solid #0f5e1f; cursor: pointer; font-weight: bold; box-shadow: 4px 4px 0px rgba(0,0,0,0.8); font-size: 16px; text-transform: uppercase; transition: 0.1s;'>Accept Nomination</button> 
                </div>
            </div>
        </div>
    `;

    let pres_container = document.createElement('div');
    pres_container.id = 'inner_window_dynamic_pres';
    pres_container.innerHTML = pres_html;
    document.body.appendChild(pres_container);

    let btn = document.getElementById('pres_continue_button');
    btn.addEventListener('click', function(e) {
        e.preventDefault();
        e.stopPropagation();
        document.getElementById('inner_window_dynamic_pres').remove(); 
    });
    
    btn.addEventListener('mousedown', function() {
        this.style.transform = 'translate(2px, 2px)';
        this.style.boxShadow = '2px 2px 0px rgba(0,0,0,0.8)';
    });
    btn.addEventListener('mouseup', function() {
        this.style.transform = 'none';
        this.style.boxShadow = '4px 4px 0px rgba(0,0,0,0.8)';
    });
}

