// 7. 2024 胜负精算引擎
let pol_cap = (typeof campaignTrail_temp !== 'undefined' && typeof campaignTrail_temp.Political_capital !== 'undefined') ? campaignTrail_temp.Political_capital : 0;
let public_discontent = (typeof campaignTrail_temp !== 'undefined' && typeof campaignTrail_temp.Discontent !== 'undefined') ? campaignTrail_temp.Discontent : (pol_cap < 0 ? Math.abs(pol_cap) : 0);

let flags = (typeof window.Election2018_Flags !== 'undefined') ? window.Election2018_Flags : {};
let ko_won_taipei = (flags['Taipei'] === 'Ko' || flags['Taipei'] === 'IND' || flags['Taipei'] !== 'KMT');
let has_high_discontent = (public_discontent >= 7 || pol_cap <= -7);
let ko_won_2024 = (has_high_discontent && p_dpp_2020 < 50.0 && ko_won_taipei);

let weight_kmt_2024 = 0; let weight_dpp_2024 = 0;

if (p_kmt_2020 >= 55.0) weight_kmt_2024 += 1.0;
else if (p_kmt_2020 >= 50.0) weight_kmt_2024 += 0.5;

if (p_dpp_2020 >= 55.0) weight_dpp_2024 += 1.0;
else if (p_dpp_2020 >= 50.0) weight_dpp_2024 += 0.5;

if (pol_cap >= 1) {
    weight_dpp_2024 += 0.5;
} else if (pol_cap < 0) {
    weight_dpp_2024 -= 0.5;
}

if (public_discontent < 3) {
    weight_dpp_2024 += 0.5;
} else if (public_discontent >= 3 && public_discontent <= 5) {
    // 不加不减 (0)
} else if (public_discontent > 5 && public_discontent < 10) {
    weight_dpp_2024 -= 0.5;
} else if (public_discontent >= 10) {
    weight_dpp_2024 -= 1.0;
}

if (isHung2020 && !kmt_2020_win) {
    weight_kmt_2024 -= 0.5;
}

if (isMa2020 && kmt_2020_win) {
    weight_kmt_2024 -= 0.5;
}

if (dpp_2024_cand === 'Lai Ching-te' && answers_history.includes(20532) && (answers_history.includes(2447) || answers_history.includes(2427))) {
    weight_dpp_2024 -= 1.0;
}

let kmt_2024_win = false;
let dpp_2024_win = false;

if (ko_won_2024) {
    kmt_2024_win = false;
    dpp_2024_win = false;
} else {
    kmt_2024_win = weight_kmt_2024 > weight_dpp_2024;
    if (weight_kmt_2024 === weight_dpp_2024) kmt_2024_win = kmt_2020_win;
    dpp_2024_win = !kmt_2024_win;
}

// 8. 2028 胜负精算引擎 (经过精细提纯去重)
let weight_kmt_2028 = 0; let weight_dpp_2028 = 0; let weight_tpp_2028 = 0;

if (ko_won_2024) {
    weight_tpp_2028 += 1.0;
    if (pol_cap >= 0) weight_tpp_2028 += 1.0;
    else weight_tpp_2028 -= 1.0;

    if (!kmt_2020_win) weight_kmt_2028 += 0.5;
    else weight_dpp_2028 += 0.5;
} else if (kmt_2024_win) {
    weight_kmt_2028 += 1.0;
    weight_dpp_2028 += 1.0;
} else {
    weight_dpp_2028 += 1.0;
    if (!kmt_2020_win) {
        weight_kmt_2028 += 0.5;
    } else {
        weight_kmt_2028 += 1.0;
    }
}

if (!kmt_2020_win && dpp_2024_win && !isHung2020) {
    weight_kmt_2028 += 0.5;
}

if (isHung2020 && !kmt_2020_win) {
    weight_kmt_2028 -= 0.5;
}

if (p_kmt_2020 < 35.0) {
    weight_kmt_2028 -= 0.5;
}

// 民怨对 2028 民进党权重的分阶影响 (统一在此处计算一次，避免重复扣分)
if (public_discontent < 3) {
    weight_dpp_2028 += 0.5;
} else if (public_discontent >= 3 && public_discontent <= 5) {
    // 保持不变
} else if (public_discontent > 5 && public_discontent < 10) {
    weight_dpp_2028 -= 0.5;
} else if (public_discontent >= 10) {
    weight_dpp_2028 -= 1.0;
}

let tpp_2028_win = ko_won_2024 && (weight_tpp_2028 >= weight_kmt_2028 && weight_tpp_2028 >= weight_dpp_2028);
let kmt_2028_win = !tpp_2028_win && (weight_kmt_2028 > weight_dpp_2028);

// 9. 动态生成维基百科单行或双行函数
function genPresRow(termStr, rowspan, party, img, nameEN, nameZH, born, startD, endD, vpText) {
    let pColor = '#1B9431';
    let pName = 'Democratic<br>Progressive Party';
    if (party === 'KMT') {
        pColor = '#000099';
        pName = 'Kuomintang';
    } else if (party === 'TPP') {
        pColor = '#33B5E5';
        pName = 'Taiwan People\'s Party';
    }
    let pStyle = 'width: 105px; height: 135px; object-fit: cover; object-position: center 10%; display: block; margin: 0 auto; border: 1px solid #ccc;';
    
    let html = '<tr style=\'border-bottom: 1px solid #f0f0f0;\'>';
    if (rowspan > 0) {
        html += `<th rowspan='${rowspan}' style='background-color: ${pColor}; color: #fff; font-weight: bold; font-size: 16px; width: 40px; border: 1px solid #a2a9b1;'>${termStr}</th>`;
        html += `<td rowspan='${rowspan}' style='border-left: 5px solid ${pColor}; border: 1px solid #a2a9b1; text-align: center; padding: 0.4em;'><img src='${img}' style='${pStyle}'></td>`;
        html += `<td rowspan='${rowspan}' style='border: 1px solid #a2a9b1; padding: 0.5em; text-align: center;'><span style='font-weight: bold; display: block; font-size: 15px;'>${nameEN}</span><span style='display: block; margin-top: 2px; font-size: 15px;'>${nameZH}</span><span style='font-size: 0.85em; color: #54595d; display: block;'>${born}</span></td>`;
    }
    html += `<td style='border: 1px solid #a2a9b1; padding: 0.5em; text-align: center;'>${startD}</td>`;
    html += `<td style='border: 1px solid #a2a9b1; padding: 0.5em; text-align: center;'>${endD}</td>`;
    if (rowspan > 0) {
        html += `<td rowspan='${rowspan}' style='border: 1px solid #a2a9b1; padding: 0.5em; text-align: center;'>${pName}</td>`;
    }
    html += `<td style='border: 1px solid #a2a9b1; padding: 0.5em; text-align: center;'>${vpText}</td>`;
    html += '</tr>';
    return html;
}

